(7696519, 1262225, 97225, '<td valign="top">I love this. This was my equal top pick along with Gaby''s (<img border="0" src="https://www.dpchallenge.com/images/user_icon/21_F.gif" xalt="'' . substr(''https://www.dpchallenge.com/images/user_icon/21_F.gif'', strrpos(''https://www.dpchallenge.com/images/user_icon/21_F.gif'', ''/'') + 1) . ''"/> <a href="https://www.dpchallenge.com/profile.php?USER_ID=141319" rel="nofollow" target="_blank">kasaba</a>)</td>', 'I love this. This was my equal top pick along with Gaby''s ( kasaba)', '2021-06-24 23:55:07.000000', NULL, 0),
(7696520, 1261666, 97225, '<td valign="top">This is fabulous. It was my equal top pick along with Mary Ann''s (<img border="0" src="https://www.dpchallenge.com/images/user_icon/21_F.gif" xalt="'' . substr(''https://www.dpchallenge.com/images/user_icon/21_F.gif'', strrpos(''https://www.dpchallenge.com/images/user_icon/21_F.gif'', ''/'') + 1) . ''"/> <a href="https://www.dpchallenge.com/profile.php?USER_ID=109227" rel="nofollow" target="_blank">grahamgator</a>)</td>', 'This is fabulous. It was my equal top pick along with Mary Ann''s ( grahamgator)', '2021-06-24 23:56:35.000000', NULL, 0),
